from flask import Flask, Blueprint, jsonify, request

# In-memory user storage
users_store = [
    {'id': 1, 'name': 'Alice', 'email': 'alice@example.com'},
    {'id': 2, 'name': 'Bob', 'email': 'bob@example.com'},
]

# Create the users blueprint
def create_users_blueprint():
    users_bp = Blueprint('users', __name__)

    @users_bp.route('/', methods=['GET'])
    def list_users():
        return jsonify(users_store)

    @users_bp.route('/<int:user_id>', methods=['GET'])
    def get_user(user_id):
        user = next((u for u in users_store if u['id'] == user_id), None)
        if user:
            return jsonify(user)
        return jsonify({'error': 'User not found'}), 404

    @users_bp.route('/', methods=['POST'])
    def create_user():
        data = request.get_json()
        new_user = {
            'id': max([u['id'] for u in users_store], default=0) + 1,
            'name': data.get('name'),
            'email': data.get('email')
        }
        users_store.append(new_user)
        return jsonify(new_user), 201

    @users_bp.route('/<int:user_id>', methods=['DELETE'])
    def delete_user(user_id):
        user = next((u for u in users_store if u['id'] == user_id), None)
        if user:
            users_store.remove(user)
            return '', 204
        return jsonify({'error': 'User not found'}), 404

    return users_bp

# Create the main Flask application
def create_app():
    app = Flask(__name__)

    # Register the users blueprint with URL prefix
    users_bp = create_users_blueprint()
    app.register_blueprint(users_bp, url_prefix='/users')

    # Main route
    @app.route('/')
    def index():
        return jsonify({'message': 'Welcome to the Flask app'})

    return app

if __name__ == '__main__':
    app = create_app()
    app.run(debug=True, host='localhost', port=5000)

